import{_ as t,a as d,c as a,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Redis 知识复盘 · 数据结构与使用边界至事务与条件更新","description":"按数据、内存、持久化、复制分片、事务、锁与缓存异常建立完整学习路径。","frontmatter":{"title":"Redis 知识复盘 · 数据结构与使用边界至事务与条件更新","description":"按数据、内存、持久化、复制分片、事务、锁与缓存异常建立完整学习路径。","splitFrom":"middleware/redis/pro/interview/redis-面试.md","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Redis 知识复盘","summary":"按数据、内存、持久化、复制分片、事务、锁与缓存异常建立完整学习路径。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":{"text":"Redis 知识复盘","link":"/middleware/redis/pro/interview/redis-%E9%9D%A2%E8%AF%95"},"next":{"text":"Redis 知识复盘 · 分布式锁与并发写至继续学习","link":"/middleware/redis/pro/interview/redis-面试-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Redis 知识复盘","link":"/middleware/redis/pro/interview/redis-%E9%9D%A2%E8%AF%95"},"next":{"text":"Redis 知识复盘 · 分布式锁与并发写至继续学习","link":"/middleware/redis/pro/interview/redis-面试-part-02"}},"headers":[],"relativePath":"middleware/redis/pro/interview/redis-面试-part-01.md","filePath":"middleware/redis/pro/interview/redis-面试-part-01.md"}'),i={name:"middleware/redis/pro/interview/redis-面试-part-01.md"};function o(l,e,s,c,n,h){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="redis-知识复盘-·-数据结构与使用边界至事务与条件更新" tabindex="-1">Redis 知识复盘 · 数据结构与使用边界至事务与条件更新 <a class="header-anchor" href="#redis-知识复盘-·-数据结构与使用边界至事务与条件更新" aria-label="Permalink to &quot;Redis 知识复盘 · 数据结构与使用边界至事务与条件更新&quot;">​</a></h1><p><a href="/middleware/redis/pro/interview/redis-面试">返回分篇目录</a></p><p>先按业务选择数据结构，再理解内存、持久化与复制，最后处理事务、锁和缓存异常。每节集中回答一类问题，避免把同一概念拆成多组问答。</p><h2 id="redis-知识复盘-数据、可靠性与缓存设计" tabindex="-1">Redis 知识复盘：数据、可靠性与缓存设计 <a class="header-anchor" href="#redis-知识复盘-数据、可靠性与缓存设计" aria-label="Permalink to &quot;Redis 知识复盘：数据、可靠性与缓存设计 {#redis-知识复盘-数据、可靠性与缓存设计}&quot;">​</a></h2><p>先按业务选择数据结构，再理解内存、持久化与复制，最后处理事务、锁和缓存异常。每节集中回答一类问题，避免把同一概念拆成多组问答。</p><p><span id="redis-面试" aria-hidden="true"></span><span id="redis" aria-hidden="true"></span></p><h2 id="data-model" tabindex="-1">数据结构与使用边界 <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;数据结构与使用边界 {#data-model}&quot;">​</a></h2><h3 id="根据访问方式选择类型" tabindex="-1">根据访问方式选择类型 <a class="header-anchor" href="#根据访问方式选择类型" aria-label="Permalink to &quot;根据访问方式选择类型 {#根据访问方式选择类型}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>需求</th><th>类型</th><th>需要考虑的边界</th></tr></thead><tbody><tr><td>缓存对象、验证码、计数器</td><td>String</td><td>序列化成本、过期时间、单值大小</td></tr><tr><td>按字段读写对象</td><td>Hash</td><td>小对象可能使用紧凑编码，不能假定永远比多个键省内存</td></tr><tr><td>两端入队出队、最近记录</td><td>List</td><td>消费确认、失败重试需要另行设计</td></tr><tr><td>去重、交并差、共同好友</td><td>Set</td><td>大集合运算可能占用执行时间</td></tr><tr><td>排行榜、按时间取到期任务</td><td>Sorted Set</td><td>分数范围、并列排序、取出与删除的原子性</td></tr></tbody></table><p>这些是常见基础类型，不代表 Redis 只有五种类型。队列还可以考虑 Stream；选型时应比较消费组、确认与重放需求，不能把 Pub/Sub 当成可靠消息存储。</p><h3 id="redis、本地缓存与-memcached" tabindex="-1">Redis、本地缓存与 Memcached <a class="header-anchor" href="#redis、本地缓存与-memcached" aria-label="Permalink to &quot;Redis、本地缓存与 Memcached {#redis、本地缓存与-memcached}&quot;">​</a></h3><p>本地缓存访问不经过网络，但各应用实例拥有独立副本；Redis 让多个实例访问同一份远程数据，也引入网络、故障和容量管理成本。共享缓存不等于缓存与数据库自动一致。</p><p>Memcached 主要提供对象缓存；Redis 还提供集合操作和可选持久化等能力。两者的延迟与吞吐取决于数据、命令、硬件和拓扑，不使用固定 QPS 或“必然快很多”作为结论。</p><p>缓存适合读多、可复用且允许明确陈旧窗口的数据。不能仅凭“更新前读取两次”判断是否值得缓存，应比较命中率、回源成本、更新成本与一致性要求。</p><h2 id="execution" tabindex="-1">执行模型与慢请求 <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;执行模型与慢请求 {#execution}&quot;">​</a></h2><h3 id="为什么快-什么操作会阻塞" tabindex="-1">为什么快，什么操作会阻塞 <a class="header-anchor" href="#为什么快-什么操作会阻塞" aria-label="Permalink to &quot;为什么快，什么操作会阻塞 {#为什么快-什么操作会阻塞}&quot;">​</a></h3><p>常见原因是内存访问、适合业务的数据结构、事件循环与 I/O 多路复用。命令执行路径与后台持久化、释放内存、网络 I/O 等线程不能混为一谈；具体线程行为取决于版本和配置。</p><p>大键、长 Lua 脚本、全量遍历和大集合运算仍可能阻塞其他请求。性能排查先看慢日志、命令复杂度、键大小、网络往返和持久化开销，不把“单线程”解释为进程只能使用一个 CPU 核。</p><h3 id="批量写入与扫描键空间" tabindex="-1">批量写入与扫描键空间 <a class="header-anchor" href="#批量写入与扫描键空间" aria-label="Permalink to &quot;批量写入与扫描键空间 {#批量写入与扫描键空间}&quot;">​</a></h3><ul><li>Pipeline 减少多次网络往返，不提供事务隔离；客户端需要限制单批数量和响应内存。</li><li><code>redis-cli --pipe</code> 适合按 Redis 协议批量导入；导入前仍需确认目标、容量和错误统计。</li><li>在线遍历优先使用游标式 <code>SCAN</code>，以返回游标再次为 <code>0</code> 为一轮结束；<code>MATCH</code> 是过滤条件，<code>COUNT</code> 是工作量提示，不保证一次返回指定条数。</li><li>扫描结果可能重复，应去重；扫描期间变更的数据不能当作一致快照。每次扫描也有开销，不能称为完全无阻塞。</li><li><code>KEYS</code> 一次扫描整个键空间，不宜直接用于大规模在线实例。</li></ul><h2 id="memory" tabindex="-1">过期与内存淘汰 <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;过期与内存淘汰 {#memory}&quot;">​</a></h2><h3 id="两种机制分别解决什么问题" tabindex="-1">两种机制分别解决什么问题 <a class="header-anchor" href="#两种机制分别解决什么问题" aria-label="Permalink to &quot;两种机制分别解决什么问题 {#两种机制分别解决什么问题}&quot;">​</a></h3><p><strong>过期</strong>根据 TTL 判断数据是否失效，Redis 通过访问时检查及主动过期等机制处理过期键。<code>EXPIRE</code> 设置有效期，<code>PERSIST</code> 取消有效期。</p><p><strong>淘汰</strong>在内存达到 <code>maxmemory</code> 限制时按配置选择可移除的键；它不替代业务 TTL，也不会自动识别哪些数据对业务更重要。</p><table tabindex="0"><thead><tr><th>策略族</th><th>候选范围</th><th>选择方式</th></tr></thead><tbody><tr><td><code>allkeys-lru</code> / <code>allkeys-lfu</code></td><td>所有键</td><td>近似最近使用 / 使用频率</td></tr><tr><td><code>volatile-lru</code> / <code>volatile-lfu</code></td><td>设置过期时间的键</td><td>近似最近使用 / 使用频率</td></tr><tr><td><code>allkeys-random</code> / <code>volatile-random</code></td><td>所有键 / 有过期时间的键</td><td>随机</td></tr><tr><td><code>volatile-ttl</code></td><td>有过期时间的键</td><td>优先更接近过期的键</td></tr><tr><td><code>noeviction</code></td><td>不主动淘汰</td><td>需要额外内存的写入可能失败</td></tr></tbody></table><h3 id="容量与热点优化" tabindex="-1">容量与热点优化 <a class="header-anchor" href="#容量与热点优化" aria-label="Permalink to &quot;容量与热点优化 {#容量与热点优化}&quot;">​</a></h3><p>先确定哪些数据可以丢失，再选择策略。记录键数量、值大小分布、命中率、淘汰量与复制/持久化峰值；为缓冲、fork 后写时复制和系统开销预留空间，不把 <code>maxmemory</code> 当成进程 RSS 的硬上限。</p><p>对象可按字段合并到 Hash，但也要防止形成大键和热点。分片能分散多个键，不能自动把一个超大 Sorted Set 拆成多份。不要在没有容量与流量证据时预先部署几十个实例。</p><h2 id="persistence" tabindex="-1">持久化与恢复选择 <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;持久化与恢复选择 {#persistence}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>保存什么</th><th>主要取舍</th></tr></thead><tbody><tr><td>RDB</td><td>某个时点的数据快照</td><td>便于备份和恢复；可能丢失快照后的更新，生成快照也有资源开销</td></tr><tr><td>AOF</td><td>写操作日志</td><td>丢失窗口与刷盘策略有关；需要考虑日志增长、重写和恢复成本</td></tr><tr><td>两者结合</td><td>日志与快照</td><td>可同时满足恢复与备份需求，仍须验证实际恢复过程</td></tr></tbody></table><p>后台生成 RDB 不等于主线程完全没有停顿或 I/O 成本；fork、写时复制和磁盘竞争都可能影响延迟。AOF 的 <code>always</code>、<code>everysec</code>、<code>no</code> 刷盘策略在延迟与丢失窗口之间取舍，不能把任何模式称为绝对零丢失。</p><p>两种持久化都启用时，重启恢复通常使用 AOF。AOF 的布局与恢复流程有版本差异，不能照旧教程直接删除日志中的某行来“撤销误操作”。先保全文件，在隔离环境按版本工具检查与恢复。</p><p>备份与主从复制用途不同：副本会同步错误写入和删除。至少保留独立备份并做恢复演练；不能为了性能笼统关闭所有主库持久化，再把副本视作唯一保障。</p><h2 id="availability" tabindex="-1">复制、故障转移与分片 <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;复制、故障转移与分片 {#availability}&quot;">​</a></h2><h3 id="主从复制先解决副本问题" tabindex="-1">主从复制先解决副本问题 <a class="header-anchor" href="#主从复制先解决副本问题" aria-label="Permalink to &quot;主从复制先解决副本问题 {#主从复制先解决副本问题}&quot;">​</a></h3><p>复制通常是异步的，副本读可能落后。首次同步或无法增量续传时需要全量同步；连接恢复后能否部分同步，取决于复制标识及积压缓冲区是否覆盖缺口。</p><p>全量同步涉及生成/传输快照、装载快照和追赶增量，不保证复制期间任何操作都毫无停顿。空主库重启也可能把空数据传播给副本，因此应结合持久化和故障恢复流程设计启动行为。</p><h3 id="sentinel-与-cluster-各负责什么" tabindex="-1">Sentinel 与 Cluster 各负责什么 <a class="header-anchor" href="#sentinel-与-cluster-各负责什么" aria-label="Permalink to &quot;Sentinel 与 Cluster 各负责什么 {#sentinel-与-cluster-各负责什么}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>解决的问题</th><th>没有自动解决的问题</th></tr></thead><tbody><tr><td>主从复制</td><td>数据副本、可选的读扩展</td><td>自动选主、写入分片、零数据丢失</td></tr><tr><td>Sentinel</td><td>监控主从、选举和故障转移、发现新主库</td><td>数据分片与强一致性</td></tr><tr><td>Redis Cluster</td><td>哈希槽分片、节点间故障处理与副本接管</td><td>跨槽任意多键事务与异步复制丢失窗口</td></tr></tbody></table><p>Sentinel 部署需要考虑 quorum、选举多数票与故障域，通常至少部署三个相互独立的 Sentinel。不能只凭“每主一从”就断言所有网络分区下都能继续服务。</p><h3 id="cluster-哈希槽与客户端重定向" tabindex="-1">Cluster 哈希槽与客户端重定向 <a class="header-anchor" href="#cluster-哈希槽与客户端重定向" aria-label="Permalink to &quot;Cluster 哈希槽与客户端重定向 {#cluster-哈希槽与客户端重定向}&quot;">​</a></h3><p>Cluster 使用 16384 个槽，键通过 CRC16 与槽数取模确定槽；<code>{...}</code> hash tag 可让有关联的键落到同槽。客户端收到 <code>MOVED</code> 或迁移中的 <code>ASK</code> 后访问正确节点，不是任意服务端替客户端透明转发命令。</p><p>扩缩容需要迁移槽与数据；副本数量独立配置，不是每个节点都天然有 N−1 个副本。Cluster 只使用数据库 0；多键操作、事务和脚本通常要求有关联的键位于同槽。支持 Cluster 的客户端可以按节点处理 Pipeline，不能笼统说集群“不支持 Pipeline”。</p><p>客户端分片将路由放在应用侧，代理分片增加中转层；两者都要明确拓扑更新、跨分片操作与备份恢复边界。副本扩容主要增加可用副本或读能力，不能替代写入分片。</p><h2 id="transactions" tabindex="-1">事务与条件更新 <a class="header-anchor" href="#transactions" aria-label="Permalink to &quot;事务与条件更新 {#transactions}&quot;">​</a></h2><h3 id="multi、exec、watch-的执行语义" tabindex="-1">MULTI、EXEC、WATCH 的执行语义 <a class="header-anchor" href="#multi、exec、watch-的执行语义" aria-label="Permalink to &quot;MULTI、EXEC、WATCH 的执行语义 {#multi、exec、watch-的执行语义}&quot;">​</a></h3><ol><li>必要时 <code>WATCH</code> 观察要读取并修改的键。</li><li>读取并在应用端计算新值。</li><li><code>MULTI</code> 开始排队，发送写命令。</li><li><code>EXEC</code> 执行；若被观察的键已变化，整个事务不执行，客户端决定是否重试。</li></ol><p><code>DISCARD</code> 放弃尚未执行的队列，<code>UNWATCH</code> 取消监视。成功执行 <code>EXEC</code> 时，队列中的命令按顺序执行，其他客户端命令不会插入其中。</p><h3 id="出错不等于关系数据库回滚" tabindex="-1">出错不等于关系数据库回滚 <a class="header-anchor" href="#出错不等于关系数据库回滚" aria-label="Permalink to &quot;出错不等于关系数据库回滚 {#出错不等于关系数据库回滚}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>失败位置</th><th>结果</th></tr></thead><tbody><tr><td>排队阶段发现命令错误</td><td>当前支持版本会在 <code>EXEC</code> 时拒绝执行该事务</td></tr><tr><td><code>WATCH</code> 条件冲突</td><td><code>EXEC</code> 返回空结果，队列不执行</td></tr><tr><td>执行时发生类型等运行错误</td><td>其他命令仍会执行，不撤销已成功的写入</td></tr></tbody></table><p>Lua 脚本也不自动回滚已发生的写入；运行错误会终止后续脚本执行。先验证输入与键类型，再执行写入。事务、脚本的持久性仍受持久化设置影响，不把“执行不被插入”直接等同完整 ACID 保证。</p>',51)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
